/*__ESM_BODY_START__*/window.process={};import{j as jsxRuntimeExports}from"./main.jsdbx";import{N as NavHeader}from"./NavHeader.jsdbx";import{i as insertStyle}from"./____insertStyle.jsdbx";insertStyle('/* Fraud Dashboard Styles */
.fraud-dashboard {
 min-height: 100vh;
 background: var(--cc-bg-primary);
 color: var(--cc-text-primary);
 font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

/* Page Title Section */
.fraud-title-section {
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 padding: var(--cc-spacing) var(--cc-spacing) 0;
 margin-bottom: var(--cc-spacing);
}

.fraud-title-left {
 display: flex;
 flex-direction: column;
 gap: 6px;
}

.fraud-title {
 font-size: 28px;
 font-weight: 700;
 color: var(--cc-text-primary);
 margin: 0;
 letter-spacing: -0.5px;
}

.fraud-subtitle {
 font-size: 14px;
 color: var(--cc-text-secondary);
 margin: 0;
}

.fraud-title-right {
 flex-shrink: 0;
}

.live-badge {
 display: inline-flex;
 align-items: center;
 gap: 6px;
 font-size: 12px;
 color: var(--cc-text-secondary);
 border: 1px solid var(--cc-border);
 border-radius: 20px;
 padding: 6px 14px;
 background: var(--cc-bg-card);
}

.live-dot {
 display: inline-block;
 width: 8px;
 height: 8px;
 border-radius: 50%;
 background: var(--cc-accent);
 box-shadow: 0 0 6px var(--cc-accent);
 animation: pulse-dot 2s infinite;
}

@keyframes pulse-dot {
 0%, 100% {
 opacity: 1;
 }
 50% {
 opacity: 0.5;
 }
}
/* KPI Cards Row */
.fraud-kpi-row {
 display: grid;
 grid-template-columns: repeat(4, 1fr);
 gap: 16px;
 padding: 0 var(--cc-spacing);
 margin-bottom: var(--cc-spacing);
}

.fraud-kpi-card {
 background: var(--cc-bg-card);
 border: 1px solid var(--cc-border);
 border-radius: var(--cc-radius);
 padding: 20px 22px;
 display: flex;
 flex-direction: column;
 gap: 6px;
}

.kpi-label {
 font-size: 11px;
 font-weight: 600;
 color: var(--cc-text-secondary);
 letter-spacing: 0.5px;
 text-transform: uppercase;
}

.kpi-value {
 font-size: 36px;
 font-weight: 700;
 color: var(--cc-text-primary);
 line-height: 1.1;
 margin: 4px 0;
}

.kpi-value.kpi-red {
 color: var(--cc-critical);
}

.kpi-value.kpi-green {
 color: var(--cc-accent);
}

.kpi-unit {
 font-size: 20px;
 font-weight: 500;
 color: var(--cc-text-secondary);
 margin-left: 2px;
}

.kpi-desc {
 font-size: 12px;
 color: var(--cc-text-secondary);
 line-height: 1.4;
}

/* Table Card */
.fraud-table-card {
 background: var(--cc-bg-card);
 border: 1px solid var(--cc-border);
 border-radius: var(--cc-radius);
 margin: 0 var(--cc-spacing) var(--cc-spacing);
 padding: 24px;
 overflow: hidden;
}

.fraud-table-header {
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 margin-bottom: 20px;
}

.fraud-table-header-left {
 display: flex;
 flex-direction: column;
 gap: 4px;
}

.fraud-table-title {
 font-size: 18px;
 font-weight: 600;
 color: var(--cc-text-primary);
 margin: 0;
}

.fraud-table-subtitle {
 font-size: 13px;
 color: var(--cc-text-secondary);
 margin: 0;
}

.fraud-table-header-right {
 flex-shrink: 0;
}

.model-badge {
 display: inline-block;
 font-size: 12px;
 color: var(--cc-text-secondary);
 border: 1px solid var(--cc-border);
 border-radius: 20px;
 padding: 6px 14px;
 background: rgba(30, 42, 69, 0.5);
}

/* Table */
.fraud-table-wrap {
 overflow-x: auto;
}

.fraud-table {
 width: 100%;
 border-collapse: collapse;
 font-size: 13px;
}

.fraud-table thead th {
 text-align: left;
 font-size: 11px;
 font-weight: 600;
 color: var(--cc-text-secondary);
 letter-spacing: 0.5px;
 text-transform: uppercase;
 padding: 12px 14px;
 border-bottom: 1px solid var(--cc-border);
 white-space: nowrap;
}

.fraud-table tbody tr {
 border-bottom: 1px solid rgba(30, 42, 69, 0.6);
 transition: background 0.15s ease;
}

.fraud-table tbody tr:hover {
 background: rgba(30, 42, 69, 0.4);
}

.fraud-table tbody tr:last-child {
 border-bottom: none;
}

.fraud-table tbody td {
 padding: 14px;
 vertical-align: middle;
}

.cell-primary {
 display: block;
 font-size: 13px;
 font-weight: 500;
 color: var(--cc-text-primary);
}

.cell-secondary {
 display: block;
 font-size: 11px;
 color: var(--cc-text-secondary);
 margin-top: 2px;
}

/* AI Confidence Column */
.confidence-cell {
 display: flex;
 align-items: center;
 gap: 10px;
 min-width: 160px;
}

.confidence-badge {
 display: inline-flex;
 align-items: center;
 justify-content: center;
 font-size: 12px;
 font-weight: 600;
 padding: 3px 8px;
 border-radius: 10px;
 min-width: 42px;
 text-align: center;
 flex-shrink: 0;
}

.confidence-high {
 background: rgba(0, 200, 150, 0.15);
 color: var(--cc-accent);
}

.confidence-medium {
 background: rgba(245, 158, 11, 0.15);
 color: var(--cc-warning);
}

/* Confidence Bars */
.confidence-bar {
 flex: 1;
 height: 6px;
 border-radius: 3px;
 background: rgba(30, 42, 69, 0.8);
 overflow: hidden;
 min-width: 80px;
}

.confidence-bar .bar-fill {
 height: 100%;
 border-radius: 3px;
 transition: width 0.3s ease;
}

.bar-red .bar-fill {
 background: linear-gradient(90deg, #ef4444, #dc2626);
}

.bar-orange .bar-fill {
 background: linear-gradient(90deg, #f59e0b, #d97706);
}

.bar-green .bar-fill {
 background: linear-gradient(90deg, #00c896, #10b981);
}

/* Reason Column */
.reason-text {
 font-size: 12px;
 color: var(--cc-text-secondary);
 line-height: 1.4;
 max-width: 280px;
 display: block;
}

/* Refund Column */
.refund-value {
 font-size: 13px;
 font-weight: 600;
 color: var(--cc-text-primary);
}

/* Decision Column */
.decision-pending-wrap {
 display: flex;
 flex-direction: column;
 gap: 8px;
}

.decision-badge {
 display: inline-flex;
 align-items: center;
 justify-content: center;
 font-size: 11px;
 font-weight: 600;
 padding: 5px 12px;
 border-radius: 16px;
 white-space: nowrap;
}

.decision-escalated {
 background: rgba(245, 158, 11, 0.15);
 color: var(--cc-warning);
}

.decision-denied {
 background: rgba(239, 68, 68, 0.15);
 color: var(--cc-critical);
}

.decision-approved {
 background: rgba(0, 200, 150, 0.15);
 color: var(--cc-accent);
}

.decision-pending {
 background: transparent;
 border: 1px solid var(--cc-border);
 color: var(--cc-text-secondary);
}

/* Action Buttons */
.decision-actions {
 display: flex;
 gap: 6px;
}

.action-btn {
 font-size: 11px;
 font-weight: 500;
 padding: 3px 10px;
 border-radius: 12px;
 cursor: pointer;
 background: transparent;
 transition: all 0.15s ease;
}

.action-btn.action-approve {
 border: 1px solid var(--cc-accent);
 color: var(--cc-accent);
}

.action-btn.action-approve:hover {
 background: rgba(0, 200, 150, 0.1);
}

.action-btn.action-escalate {
 border: 1px solid var(--cc-warning);
 color: var(--cc-warning);
}

.action-btn.action-escalate:hover {
 background: rgba(245, 158, 11, 0.1);
}

.action-btn.action-deny {
 border: 1px solid var(--cc-critical);
 color: var(--cc-critical);
}

.action-btn.action-deny:hover {
 background: rgba(239, 68, 68, 0.1);
}

/* Responsive */
@media (max-width: 1200px) {
 .fraud-kpi-row {
 grid-template-columns: repeat(2, 1fr);
 }
}
@media (max-width: 768px) {
 .fraud-kpi-row {
 grid-template-columns: 1fr;
 }
 .fraud-title-section {
 flex-direction: column;
 gap: 12px;
 }
 .fraud-table-header {
 flex-direction: column;
 gap: 12px;
 }
